import { motion, useScroll, useTransform } from "framer-motion";
import Image from "next/image";
import styles from "./TxBandAnimated.module.css";

const txBands = [0, 1, 2, 3, 4];

export default function TxBandAnimated() {
  const { scrollY } = useScroll();

  return (
    <div className={styles.diagonalRow}>
      {txBands.map((band, i) => {
        // Décalage horizontal et vertical selon l'index et le scroll
        const x = useTransform(scrollY, [0, 500], [0, 100 + i * 60]);
        const y = useTransform(scrollY, [0, 500], [0, i * 60]);
        return (
          <motion.div
            key={i}
            style={{ x, y }}
            className={styles.txband}
          >
            <Image
              src="/txband.png"
              alt={`TxBand ${i + 1}`}
              width={120}
              height={42}
            />
          </motion.div>
        );
      })}
    </div>
  );
}